declarations.Position:
export interface Position {
  x: number;
  y: number;
}

declarations.ScreenshotContentTransform:
// Screen-space pan/zoom of the screenshot content inside the device frame.
// Offsets are fractions of the screen area (positive x moves content right);
// zoom >= 1 so the content always covers the screen without gaps.
export interface ScreenshotContentTransform {
  x: number;
  y: number;
  zoom: number;
}

declarations.DeviceModelId:
// The 3D device models the renderer can load. Declared here (the dependency-free
// base of the type graph) so the mockups state, the layout config and the API
// schemas all narrow to the same union instead of restating it — adding a model
// used to mean four synchronized edits with no compiler pressure.
export type DeviceModelId =
  | "iphone-17-pro"
  | "google-pixel-10-pro"
  | "ipad-pro"
  | "macbook-pro-14";

declarations.Model3DConfig:
// Real 3D glTF device model (rendered offscreen via Three.js, composited into
// the PIXI canvas as a sprite). Shares its look with the mockups editor.
export interface Model3DConfig {
  modelId?: DeviceModelId;
  /**
   * Per-platform phone appearance; pose and scale remain shared.
   * Flat modelId/finish remain the active rendering values for legacy clients.
   * Switching platforms snapshots them before restoring the target selection.
   */
  devicesByPlatform?: Partial<
    Record<
      "ios" | "android",
      {
        modelId: DeviceModelId;
        finish: Model3DConfig["finish"];
      }
    >
  >;
  finish:
    | "silver"
    | "cosmic-orange"
    | "deep-blue"
    | "pixel-obsidian"
    | "pixel-porcelain"
    | "pixel-moonstone";
  rotationX: number; // Pitch (radians)
  rotationY: number; // Yaw (radians)
  rotationZ: number; // Roll (radians)
  scale?: number; // Legacy model-space zoom. New layouts use ScreenshotNode.scale.
  showDynamicIsland?: boolean; // Legacy per-node setting. Theme phone camera setting controls this now.
  /**
   * Laptop lid angle: 0 closed, 1 fully open. Only meaningful for articulated
   * models (the MacBook); undefined reads as fully open.
   */
  lidOpen?: number;
}

