declarations.TextBoxContract:
/**
 * Fixed template-owned text container.
 *
 * `referenceContent` is the exact rapid-development/mock copy for this node.
 * The renderer measures it with the active font and width, then keeps that
 * measured height while fitting generated copy inside the same box.
 */
export interface TextBoxContract {
  mode: "shrink-to-fit";
  referenceContent: TiptapJSON;
  minFontScale: number;
  /** Identifies template text boxes that intentionally share one geometry. */
  symmetryGroup?: string;
  /**
   * When false the fit ignores the copy below it. Set once the user has moved
   * the text by hand: a dragged headline should pass over its neighbours, not
   * shrink into the gap above them.
   */
  avoidNeighbors?: boolean;
}

declarations.TextFitContract:
export interface TextFitContract {
  mode: "shrink-to-fit";
  minFontScale: number;
}

declarations.TextNode:
export interface TextNode {
  id: string;
  layerName?: string; // Optional user-facing name in the layer stack
  richContent: TiptapJSON; // Rich text content (Tiptap format) - required, contains all content and style properties
  position: Position;
  zIndex: number;
  align?: "left" | "center" | "right";
  type?: "title" | "subtitle" | "body" | "brands";
  lineHeight?: number; // Line spacing multiplier (e.g., 1.2)
  width?: number; // Optional max width for text wrapping
  textBox?: TextBoxContract; // Template-owned box used to fit generated copy
  overflow?: boolean; // Allow text to overflow to adjacent screens
  rotation?: number; // Rotation in degrees
  opacity?: number; // Transparency 0-100 (default 100 = fully opaque)
  hidden?: boolean; // Hide in editor/export layer rendering
  locked?: boolean; // Prevent direct canvas interaction
  shadow?: ShadowConfig; // Drop shadow configuration
  backgroundColor?: string; // Optional text background fill
  backgroundPaddingX?: number; // Horizontal background padding in pixels
  backgroundPaddingY?: number; // Vertical background padding in pixels
  backgroundCornerRadius?: number; // Rounded background corners in pixels
  colorRefs?: ColorRefs; // Optional links from color fields (e.g. backgroundColor) to theme roles
}

