declarations.IllustrationNode:
// Illustration element (decorative images)
export interface IllustrationNode extends BaseNode {
  type: "illustration";
  assetKind?: IllustrationAssetKind;
  path?: string; // Relative path stored in DB (e.g., "illustrations/1234-ill.png")
  signedUrl?: string; // Added at runtime by RSC for rendering
  imageUrl?: string; // Legacy URL field for migration compatibility
  scale?: number; // Scale factor for resizing
  // Logical width at scale 1. New library insertions use this to distinguish
  // full illustrations from compact icons while legacy nodes keep the 150px
  // SVG fallback in the renderer.
  referenceWidth?: number;
  width?: number;
  height?: number;
  rotation?: number; // Rotation in degrees
  tiltAngle?: number; // 3D perspective tilt (-30 to 30 degrees)
  primaryColor?: string; // Primary color for SVG illustrations (CSS filter-based tinting)
  cornerRadius?: number; // Normalized (0–1) or legacy source-pixel radius for raster illustrations like app icons
  anchor?: { x: number; y: number }; // Anchor point (default 0.5, 0.5 = center)
  // Normalized crop rect (each 0–1) over the source image. Absent/full = no crop.
  // The illustration resizes to the cropped region (see createIllustration).
  cropRegion?: CropRegion;
}

