declarations.ASOCopyTranslation:
export interface ASOCopyTranslation {
  /** Optional locale-specific store name/title. Falls back to project metadata. */
  appName?: string;
  promotionalText: string; // Editable promotional text
  shortDescription: string; // 1-2 lines, primary benefit only
  fullDescription: string; // Ready-to-paste store description with no internal section labels
  keywords: string; // Comma-separated keywords for App Store (no spaces after commas)
  insights: CopyInsights; // Insights explaining why the copy is effective
}

declarations.ASOCopy:
export interface ASOCopy extends ASOCopyTranslation {
  category: string; // Suggested App Store category
  subcategory: string; // Suggested subcategory (required)
  competitorAppIds?: Array<number | string>; // Store IDs of analyzed competitors
  competitorStoreProvider?: "app_store" | "google_play";
  competitorTargets?: Array<{
    appId: number | string;
    storeProvider: "app_store" | "google_play";
  }>;
  translations?: Record<string, ASOCopyTranslation>; // Localized ASO copy keyed by language code
  /** Per-language hash of the source copy each translation was produced from —
   * lets the translate route skip languages whose source hasn't changed. */
  translationSourceHashes?: Record<string, string>;
}

declarations.extractTranslationCopy:
/** Extract translation-relevant fields from an ASOCopy object. */
export function extractTranslationCopy(asoCopy: ASOCopy): ASOCopyTranslation {
  return {
    promotionalText: asoCopy.promotionalText,
    shortDescription: asoCopy.shortDescription,
    fullDescription: asoCopy.fullDescription,
    keywords: asoCopy.keywords,
    insights: asoCopy.insights,
  };
}

declarations.positionSchema:
const positionSchema = z
  .object({
    x: z.number(),
    y: z.number(),
  })
  .passthrough();

declarations.shadowSchema:
const shadowSchema = z
  .object({
    color: colorSchema,
    blur: z.number(),
    offsetX: z.number(),
    offsetY: z.number(),
  })
  .passthrough();

declarations.tiptapMarkSchema:
const tiptapMarkSchema = z
  .object({
    type: z.string().min(1),
    attrs: z.record(z.string(), z.unknown()).optional(),
  })
  .passthrough();

declarations.tiptapInlineNodeSchema:
const tiptapInlineNodeSchema: z.ZodType<Record<string, unknown>> = z
  .object({
    type: z.string().min(1),
    text: z.string().optional(),
    marks: z.array(tiptapMarkSchema).optional(),
  })
  .passthrough();

declarations.tiptapBlockNodeSchema:
const tiptapBlockNodeSchema: z.ZodType<Record<string, unknown>> = z
  .object({
    type: z.string().min(1),
    content: z.array(tiptapInlineNodeSchema).optional(),
  })
  .passthrough();

declarations.tiptapJSONSchema:
export const tiptapJSONSchema: z.ZodType<TiptapJSON> = z
  .object({
    type: z.literal("doc"),
    content: z.array(tiptapBlockNodeSchema),
    attrs: z.record(z.string(), z.unknown()).optional(),
  })
  .passthrough() as unknown as z.ZodType<TiptapJSON>;

declarations.badgeNodeSchema:
const badgeNodeSchema = baseNodeSchema
  .extend({
    type: z.literal("badge").optional(),
    text: z.string(),
    subtext: z.string().optional(),
    size: z.number(),
