declarations.gradientSchema:
const gradientSchema = z
  .object({
    type: z.enum(["linear", "radial"]),
    colors: z.array(colorSchema).min(2),
    direction: z.number().optional(),
  })
  .passthrough();

declarations.backgroundImageSchema:
const backgroundImageSchema = z
  .object({
    url: z.string(),
    storagePath: z.string().optional(),
    blur: z.number().optional(),
    verticalOffset: z.number().optional(),
    horizontalOffset: z.number().optional(),
    attribution: z.record(z.string(), z.unknown()).optional(),
  })
