}

declarations.PREVIEW_FORMAT_OPTIONS:
// Generate preview format options from the dimension constants (single source of truth)
export const PREVIEW_FORMAT_OPTIONS: PreviewFormatOption[] = [
  // App Store formats
  ...(
    Object.entries(APP_STORE_VIDEO_DIMENSIONS) as [
      AppStoreDisplaySize,
      (typeof APP_STORE_VIDEO_DIMENSIONS)[AppStoreDisplaySize],
    ][]
  ).map(([size, dims]) => ({
    value: `appStore:${size}` as PreviewFormat,
    label: size === "default" ? "App Store" : `${size}" iPhone`,
    width: dims.width,
    height: dims.height,
    category: "App Store" as const,
  })),
  // iPad formats
  ...(
    Object.entries(IPAD_VIDEO_DIMENSIONS) as [
      IpadDisplaySize,
      (typeof IPAD_VIDEO_DIMENSIONS)[IpadDisplaySize],
    ][]
  ).map(([size, dims]) => ({
    value: `ipad:${size}` as PreviewFormat,
    label: dims.label,
    width: dims.width,
    height: dims.height,
    category: "iPad" as const,
  })),
  // Social Media formats
  ...(
    Object.entries(SOCIAL_VIDEO_DIMENSIONS) as [
      SocialAspectRatio,
      (typeof SOCIAL_VIDEO_DIMENSIONS)[SocialAspectRatio],
    ][]
  ).map(([ratio, dims]) => ({
    value: `social:${ratio}` as PreviewFormat,
    label:
      ratio === "9:16"
        ? "9:16 Portrait"
        : ratio === "1:1"
          ? "1:1 Square"
          : "16:9 Landscape",
    width: dims.width,
    height: dims.height,
    category: "Social Media" as const,
  })),
];

declarations.getPreviewDimensions:
export function getPreviewDimensions(format: PreviewFormat): {
  width: number;
  height: number;
} {
  const option = PREVIEW_FORMAT_OPTIONS.find((opt) => opt.value === format);
  if (option) {
    return { width: option.width, height: option.height };
  }
  // Default to App Store Preview
  return { width: VIDEO_WIDTH, height: VIDEO_HEIGHT };
}

