declarations.migrateLidOpenToKeyframes:
/**
 * Projects saved before the lid became keyframable carry one project-wide
 * `lidOpen`. Push it onto every keyframe on load so the timeline is the single
 * source of truth from then on; already-migrated states pass through untouched.
 */
export function migrateLidOpenToKeyframes(
  keyframes: MockupKeyframe[],
  legacyLidOpen: number | undefined,
): MockupKeyframe[] {
  if (legacyLidOpen === undefined) return keyframes;
  if (keyframes.some((frame) => frame.lidOpen !== undefined)) return keyframes;
  return keyframes.map((frame) => ({ ...frame, lidOpen: legacyLidOpen }));
}

