declarations.LAPTOP_LID_BY_KEYFRAME:
/**
 * Laptop lid choreography: one openness value per keyframe of the preset, in
 * order, so the hinge lands exactly on the beats the motion already has instead
 * of being resampled onto them. Presets whose first and last pose match
 * (hero-launch, pivot-showcase) close the lid again at the end so the loop
 * stays seamless; the two that end elsewhere leave it open.
 */
const LAPTOP_LID_BY_KEYFRAME: Record<ScenePresetId, readonly number[]> = {
  // Swings in shut, opens as it settles face-on, closes as it swings back out.
  "hero-launch": [0.05, 1, 1, 0.05],
  // Spins shut, and is open by the time the screen faces the camera.
  "pivot-showcase": [0.08, 1, 1, 0.08],
  // Drops in closed like a laptop being set down, opens once it has landed.
  "slow-rotate": [0, 0.15, 1, 1, 1],
  // Starts ajar and opens through the punch-in.
  "drifting-tilt": [0.4, 1, 1, 1],
};

declarations.getScenePresetForDevice:
/**
 * The authored presets use phone-sized movement. Keep their timing and
 * character, but reduce travel, rotation and zoom for wider devices so every
 * preset stays framed on tablet and desktop models. Laptops additionally get
 * the lid animated along the way.
 */
export function getScenePresetForDevice(
  presetId: ScenePresetId,
  deviceKind: ScenePresetDeviceKind,
) {
  const preset = SCENE_PRESETS.find((item) => item.id === presetId);
  if (!preset) return null;

  const factors =
    deviceKind === "tablet"
      ? { position: 0.75, rotation: 0.65, scale: 0.72 }
      : deviceKind === "laptop"
        ? { position: 0.5, rotation: 0.24, scale: 0.38 }
        : { position: 1, rotation: 1, scale: 1 };
  const lidByKeyframe =
    deviceKind === "laptop" ? LAPTOP_LID_BY_KEYFRAME[presetId] : null;

  return {
    ...preset,
    state: {
      ...preset.state,
      keyframes: preset.state.keyframes.map((frame, index) => ({
        ...frame,
        x: frame.x * factors.position,
        y: frame.y * factors.position,
        rotationX: frame.rotationX * factors.rotation,
        rotationY: frame.rotationY * factors.rotation,
        rotationZ: frame.rotationZ * factors.rotation,
        scale: 1 + (frame.scale - 1) * factors.scale,
        // A short list would silently leave later keyframes lidless, so fall
        // back to the last authored value rather than to "open".
        ...(lidByKeyframe
          ? {
              lidOpen:
                lidByKeyframe[index] ?? lidByKeyframe[lidByKeyframe.length - 1],
            }
          : {}),
      })),
    },
  };
}

