declarations.deviceWindow:
export function deviceWindow(timing: MockupDeviceTiming, duration: number) {
  const start = Math.max(
    0,
    Math.min(duration - MIN_DEVICE_DURATION, timing.start),
  );
  const end = Math.max(
    start + MIN_DEVICE_DURATION,
    Math.min(duration, timing.end ?? duration),
  );
  return { start, end, duration: end - start };
}

declarations.toLocalProgress:
/** Composition progress (0..1) -> progress inside one device's window. */
export function toLocalProgress(
  window: DeviceWindow,
  globalProgress: number,
  duration: number,
) {
  return Math.max(
    0,
    Math.min(1, (globalProgress * duration - window.start) / window.duration),
  );
}

declarations.toGlobalProgress:
/** Progress inside one device's window -> composition progress (0..1). */
export function toGlobalProgress(
  window: DeviceWindow,
  localProgress: number,
  duration: number,
) {
  return (window.start + localProgress * window.duration) / duration;
}

declarations.getPlaybackTime:
/** Composition time in seconds: the looping wall clock, or the scrubbed frame. */
export function getPlaybackTime({
  isPlaying,
  animationStartedAtMs,
  speed,
  previewProgress,
  motionDuration,
}: {
  isPlaying: boolean;
  animationStartedAtMs: number;
  speed: number;
  previewProgress: number;
  motionDuration: number;
}) {
  return isPlaying
    ? (((performance.now() - animationStartedAtMs) / 1000) * speed) %
        motionDuration
    : previewProgress * motionDuration;
}

declarations.deviceFrame:
/** Shared clock for preview, video textures, timeline and cloud export. */
export function deviceFrame(
  timing: MockupDeviceTiming,
  time: number,
  duration: number,
) {
  const window = deviceWindow(timing, duration);
  const progress = Math.max(
    0,
    Math.min(1, (time - window.start) / window.duration),
  );
  const visible =
    time >= window.start &&
    (time < window.end || (time === duration && window.end === duration));
  const transition = Math.min(timing.transitionDuration, window.duration / 2);
  // Progress through the entrance/exit; a zero-length transition is complete.
  const phase = (elapsed: number) =>
    transition > 0 ? Math.max(0, Math.min(1, elapsed / transition)) : 1;
  const ease = (t: number) => t * t * (3 - 2 * t);
  // Travel quickly into view, then settle without overshoot. Keep moving
  // models solid: fading individual 3D meshes exposes their back faces.
  const settle = (t: number) => 1 - Math.pow(1 - t, 3);
  const entering = phase(time - window.start);
  const exiting = phase(window.end - time);
  const enter = ease(entering);
  const exit = ease(exiting);
  const enterMotion = settle(entering);
  const exitMotion = settle(exiting);
  return {
    ...window,
    progress,
    visible,
    opacity:
      (timing.entrance === "fade" ? enter : 1) *
      (timing.exit === "fade" ? exit : 1),
    offsetY:
      (timing.entrance === "slide" ? (1 - enterMotion) * -5 : 0) +
      (timing.exit === "slide" ? (1 - exitMotion) * -5 : 0),
    scale:
      (timing.entrance === "scale" ? enterMotion : 1) *
      (timing.exit === "scale" ? exitMotion : 1),
  };
}

