declarations.DeviceStillFraming:
/**
 * Offscreen still framing for editor composites, per model.
 *
 * `widthFactor` is the still canvas width as a fraction of the layout canvas
 * width; `aspect` is height/width — above 1 for the portrait handhelds, below 1
 * for the landscape laptop. Transparent margin is trimmed after rendering
 * (`trimTransparentCanvasWithMeta`), so an over-generous box only costs
 * effective resolution, while an under-sized one clips the device.
 */
interface DeviceStillFraming {
  widthFactor: number;
  aspect: number;
}

declarations.DeviceScreenInsets:
/**
 * The display area inside the trimmed still, as fractions of the sprite. Drives
 * the drag/hit bounds and the hover overlay, so it wants to track the glass, not
 * the chassis — a laptop's screen sits in the upper half above its base.
 */
interface DeviceScreenInsets {
  x: number;
  y: number;
  width: number;
  height: number;
  radius: number;
}

declarations.DeviceModelSpec:
interface DeviceModelSpec {
  path: string;
  baseScale: number;
  modelOffset: [number, number, number];
  label: string;
  kind: DeviceModelKind;
  screenMaterialNames: readonly string[];
  /**
   * Display aspect (width/height) of the model's screen surface, used to shape
   * the composited screen texture for non-stretch fit modes. The screen mesh's
   * UVs span 0..1 across the whole display, so a texture of any other shape is
   * distorted onto it - which is exactly what `stretch` is, and what `cover` /
   * `contain` have to counteract.
   *
   * The iPhone and Pixel derive theirs from the geometry constants above, so
   * they cannot drift from the quads actually drawn. The other two are measured
   * from their GLB's screen-mesh POSITION accessor bounds - the meshes come
   * from the asset, so there is nothing in the repo to derive them from:
   *   iPad Pro       0.5522  / 0.73035 ("Screen")
   *   MacBook Pro 14 30.07597 / hypot(6.69185, 18.37419) - the lid is authored
   *                  at 69.99 degrees, so the panel's height is the tilted
   *                  diagonal, not the raw Z extent (1.538 = the real 3024x1964
   *                  panel, which confirms the correction).
   */
  screenAspect: number;
  /**
   * True when the GLB's screen UVs run right-to-left, which renders the
   * screenshot mirrored. Decoded from each model's TEXCOORD_0: U correlates
   * with the mesh's local x at +1.000 on the Pixel and the MacBook, but at
   * -1.000 on the iPad. (The iPhone's screen is our own quad, whose -x UVs are
   * cancelled by the mesh's 180-degree Z rotation.)
   */
  screenMirrorX?: boolean;
  supportsCameraHole: boolean;
  still: DeviceStillFraming;
  screenInsets: DeviceScreenInsets;
  hiddenNodeNamePatterns?: readonly RegExp[];
  articulation?: DeviceModelArticulation;
}

