declarations.getDefaultLayoutScaleForDeviceModel:
/**
 * Layout scale applied when a device is first added as a 3D model.
 *
 * The still is trimmed to the device's silhouette before it becomes a sprite,
 * so how much canvas a given scale buys depends on how much of its still frame
 * the device fills. A phone is narrow inside a portrait frame and needs scaling
 * up; the laptop nearly fills a landscape frame and needs scaling down.
 */
export function getDefaultLayoutScaleForDeviceModel(
  deviceModelId: DeviceModelId,
): number {
  const kind = DEVICE_MODEL_SPECS[deviceModelId].kind;
  if (kind === "laptop") return 0.8;
  if (kind === "tablet") return 1.2;
  return DEVICE_DEFAULT_LAYOUT_SCALE;
}

