 * inherited roll makes the keyboard and display look accidentally crooked.
 */
export function getDefaultPoseForDeviceModel() {
  // Kept in the signature: callers already resolve the model, and the default
  // was chassis-specific until laptops and handhelds converged on Front.
  return { ...DEVICE_DEFAULT_POSE };
}

