    kinds: ["phone", "tablet"],
  },
];

declarations.getPosePresetsForDeviceModel:
/** The pose presets worth offering for a given model. */
export function getPosePresetsForDeviceModel(
  deviceModelId: DeviceModelId,
): Model3DPosePreset[] {
  const kind = DEVICE_MODEL_SPECS[deviceModelId].kind;
  return MODEL_3D_POSE_PRESETS.filter(
    (preset) => !preset.kinds || preset.kinds.includes(kind),
  );
}

declarations.matchesPosePreset:
export function matchesPosePreset(
  preset: Model3DPosePreset,
  pose: { rotationX: number; rotationY: number; rotationZ: number },
): boolean {
  const eps = 0.01;
  return (
    Math.abs(preset.rotationX - pose.rotationX) < eps &&
    Math.abs(preset.rotationY - pose.rotationY) < eps &&
    Math.abs(preset.rotationZ - pose.rotationZ) < eps
  );
}

declarations.getDeviceModelIdForPlatform:
export function getDeviceModelIdForPlatform(
  platform: "ios" | "android",
): DeviceModelId {
  return platform === "android" ? "google-pixel-10-pro" : "iphone-17-pro";
}

declarations.getDeviceModelIdForKind:
/** Resolves a create-flow device choice to the model the studio will render. */
export function getDeviceModelIdForKind(
  kind: DeviceModelKind,
  platform: "ios" | "android" = "ios",
): DeviceModelId {
  if (kind === "tablet") return "ipad-pro";
  if (kind === "laptop") return "macbook-pro-14";
  return getDeviceModelIdForPlatform(platform);
}

declarations.getDeviceModelIdForPhoneId:
export function getDeviceModelIdForPhoneId(phoneId: string): DeviceModelId {
  return phoneId === PhoneId.GooglePixel
    ? "google-pixel-10-pro"
    : "iphone-17-pro";
}

declarations.getDeviceModelIdForScreenshotDevice:
/**
 * The 3D model that stands in for a screenshot node's 2D frame.
 *
 * A node carries exactly one of phoneId/tabletId/desktopId/watchId. Watches have
 * no 3D model, so they resolve to null and callers keep the 2D frame. Which
 * phone it is depends on the layout's platform; tablet and desktop each have a
 * single model, so their ids don't participate.
 */
export function getDeviceModelIdForScreenshotDevice(
  device: {
    phoneId?: string;
    tabletId?: string;
    desktopId?: string;
    watchId?: string;
  },
  platform: "ios" | "android" = "ios",
): DeviceModelId | null {
  if (device.watchId) return null;
  if (device.desktopId) return "macbook-pro-14";
  if (device.tabletId) return "ipad-pro";
  if (device.phoneId) return getDeviceModelIdForPhoneId(device.phoneId);
  return getDeviceModelIdForPlatform(platform);
}

declarations.getDeviceModelIdForScreenshotCategory:
/**
 * Same mapping for the editor's device categories, which say "desktop" where
 * the 3D models say "laptop". Watches have no model.
 */
export function getDeviceModelIdForScreenshotCategory(
  category: "phone" | "tablet" | "desktop" | "watch",
  platform: "ios" | "android" = "ios",
): DeviceModelId | null {
  if (category === "watch") return null;
  return getDeviceModelIdForKind(
    category === "desktop" ? "laptop" : category,
    platform,
  );
}

declarations.supportsModel3D:
/** Whether a screenshot node can be rendered as a 3D device at all. */
export function supportsModel3D(device: {
  phoneId?: string;
  tabletId?: string;
  desktopId?: string;
  watchId?: string;
}): boolean {
  return !device.watchId;
}

declarations.getDefaultPhoneIdForPlatform:
export function getDefaultPhoneIdForPlatform(
  platform: "ios" | "android",
): PhoneId {
  return platform === "android" ? PhoneId.GooglePixel : PhoneId.iPhone17ProMax;
}

declarations.getDefaultFinishForDeviceModel:
export function getDefaultFinishForDeviceModel(
  deviceModelId: DeviceModelId,
): Finish {
  // Deep blue is the house iPhone finish: it holds an edge against both light
  // and dark template backgrounds, where silver washes out on pale panels.
  return deviceModelId === "google-pixel-10-pro"
    ? "pixel-obsidian"
    : "deep-blue";
}

declarations.getFinishKeysForDeviceModel:
export function getFinishKeysForDeviceModel(
  deviceModelId: DeviceModelId,
): readonly Finish[] {
  if (deviceModelId === "google-pixel-10-pro") return PIXEL_FINISH_KEYS;
  if (deviceModelId === "iphone-17-pro") return IPHONE_FINISH_KEYS;
  return ["silver"];
}

declarations.getScreenshotDeviceTypeForKind:
/** Storage folder that holds the screenshots a given device kind can display. */
export function getScreenshotDeviceTypeForKind(
  kind: DeviceModelKind,
): "mobile" | "tablet" | "desktop" {
  if (kind === "tablet") return "tablet";
  if (kind === "laptop") return "desktop";
  return "mobile";
}

declarations.getScreenshotDeviceTypeForDeviceModel:
export function getScreenshotDeviceTypeForDeviceModel(
  deviceModelId: DeviceModelId,
): "mobile" | "tablet" | "desktop" {
  return getScreenshotDeviceTypeForKind(DEVICE_MODEL_SPECS[deviceModelId].kind);
}

declarations.getDeviceSampleScreenshot:
export function getDeviceSampleScreenshot(
  deviceModelId: DeviceModelId,
): string {
  const kind = DEVICE_MODEL_SPECS[deviceModelId].kind;
  if (kind === "tablet") return "/sample-ss/ipad.jpg";
  if (kind === "laptop") return "/sample-ss/desktop.jpg";
  return DEVICE_SAMPLE_SCREENSHOT;
}

